// Uma URL por item; o nó seguinte busca todas. Para adicionar fonte, inclua
// a URL aqui e trate o formato da resposta em "Montar vagas".
const REMOTAR = ['estágio', 'estagio', 'júnior', 'junior', 'trainee'];
const GITHUB = ['frontendbr/vagas', 'backend-br/vagas', 'react-brasil/vagas', 'soujava/vagas-java'];
const HIMALAYAS = [
  'q=desenvolvedor&sort=recent',
  'q=estagio&sort=recent',
  'q=developer&country=Brazil&seniority=Entry-level&sort=recent',
];

// Gupy: a página de busca do portal (portal.gupy.io/job-search) já vem com as
// 12 vagas mais recentes no HTML (__NEXT_DATA__); a API antiga saiu do ar.
// Só tipo estágio, mais novas primeiro. Remoto do Brasil todo + o estado de
// "Montar vagas" (ESTADO_LOCAL) para presencial/híbrido.
const GUPY_BASE = 'type=vacancy_type_internship&sortBy=publishedDate&sortOrder=desc';
const GUPY = [
  'term=estágio&workplaceTypes=remote',
  'term=estágio ti&workplaceTypes=remote',
  'term=estágio desenvolvimento&workplaceTypes=remote',
  'term=estágio dados&workplaceTypes=remote',
  'term=estágio&state=Piauí',
  'term=estágio ti',
  'term=estágio desenvolvimento',
  'term=estágio dados',
  'term=estágio software',
  'term=estágio sistemas',
  'term=estágio suporte',
];

// Token do GitHub (GITHUB_TOKEN no GitHub Actions) sobe o limite de 60 para
// 1000 req/h. Sem ele (n8n local) a busca segue sem autenticação.
let githubAuth = '';
try {
  if ($env.GITHUB_TOKEN) githubAuth = `Bearer ${$env.GITHUB_TOKEN}`;
} catch {
  // acesso a $env bloqueado no n8n local: sem token
}

const gupyUrl = (q) =>
  'https://portal.gupy.io/job-search/' + encodeURIComponent(`${q}&${GUPY_BASE}`).replace(/%3D/g, '=').replace(/%26/g, '&');

return [
  ...REMOTAR.map((q) => ({ json: { url: `https://api.remotar.com.br/jobs?search=${encodeURIComponent(q)}` } })),
  ...GITHUB.map((repo) => ({
    json: {
      url: `https://api.github.com/repos/${repo}/issues?state=open&per_page=50&sort=created&direction=desc`,
      auth: githubAuth,
    },
  })),
  ...HIMALAYAS.map((q) => ({ json: { url: `https://himalayas.app/jobs/api/search?${q}` } })),
  ...GUPY.map((q) => ({ json: { url: gupyUrl(q) } })),
];

// Recebe as respostas de todas as fontes e devolve as vagas candidatas no
// formato do webhook do VagaSync: { description, url, source, title, company }.
// title e company vão como a fonte publicou (company vazio se a fonte não
// informa): o VagaSync usa os dois para deduplicar antes da IA.
//
// Perfil buscado: estágio (prioridade), trainee e júnior, área de tecnologia,
// vaga brasileira em português que não exige inglês nem anos de experiência.
// Remoto de qualquer lugar; presencial/híbrido só em CIDADES_LOCAIS /
// ESTADO_LOCAL. Ajuste as constantes abaixo para mudar o perfil.
//
// Daqui as candidatas vão para "Checar já cadastradas" (uma chamada só, que
// devolve quais ainda não existem: mesma URL ou mesmo título + empresa de outra
// fonte) e "Separar novas" aplica o teto de envios da rodada só sobre elas.

const JANELA_HORAS = 168;        // só vagas publicadas nos últimos 7 dias
const JANELA_HORAS_GUPY = 720;   // estágio na Gupy fica aberto semanas: 30 dias, se o prazo não passou
const MAX_CANDIDATAS = 300;      // limite do /api/webhook/n8n/check; o teto de envios fica em "Separar novas"
const MAX_DESCRICAO = 7500;      // o VagaSync recusa acima de 8000 caracteres

// Presencial/híbrido só daqui (a Gupy também é buscada por esse estado em "Fontes")
const ESTADO_LOCAL = 'Piauí';
const CIDADES_LOCAIS = ['Teresina'];
const LOCAL_OK = /teresina|piau[ií]|\bPI\b/i;
const PRESENCIAL = /presencial|h[ií]brid|on-?site|hybrid/i;
const REMOTO = /remot|home ?office|anywhere/i;

const NIVEL_OK = /est[aá]gi|trainee|aprendiz|j[uú]nior|\bjr\.?\b|entry[- ]level|sem experi[eê]ncia|primeiro emprego/i;
const ESTAGIO = /est[aá]gi/i;
// "Desenvolvimento de Negócios" não é TI
const AREA_FORA = /desenvolvimento (de )?(neg[oó]cios|humano|organizacional|pessoas|mercado|produtos? f[ií]sic)/i;
const NIVEL_FORA = /s[eê]nior|\bsr\.?\b|pleno|\bmid[- ]level|especialista|\blead\b|l[ií]der|staff|principal|coordenad|gerente|head\b|arquitet/i;
// A área sai do título (e das categorias, no Remotar): a descrição costuma ter
// "autodesenvolvimento", "sistemas de gestão" etc. em vaga de qualquer área.
// "programa" sozinho pegaria "Programa de Estágio" de qualquer área
const AREA_TI = /desenvolv|developer|\bdev\b|programa[çc][aã]o|programador|software|front[- ]?end|back[- ]?end|full[- ]?stack|mobile|\bweb\b|dados|\bdata\b|analytics|\bbi\b|\bqa\b|qualidade de software|testes? de software|automa[çc][aã]o de testes|devops|cloud|infra|sysadmin|suporte t[eé]cnico|help ?desk|\bti\b|tecnologia da informa|sistemas|python|java|react|node|\.net|php|sql|rpa|ciberseguran|seguran[cç]a da informa|ci[eê]ncia da computa/i;
// Título de outra área. Só derruba se o título não tiver nada de TI
// ("Analista de Dados de Marketing" continua valendo).
const NAO_TI = /marketing|vendas|comercial|pr[eé][- ]?vendas|\bsales\b|recursos humanos|\brh\b|jur[ií]dic|direito|administrativ|financeir|cont[aá]b|log[ií]stic|compras|atendimento ao cliente|social media|comunica[çc][aã]o|design gr[aá]fico|engenharia (civil|mec[aâ]nica|el[eé]trica|qu[ií]mica|de produ)/i;
const EXIGE_INGLES = /ingl[eê]s (fluente|avan[cç]ado|intermedi)|fluent english|advanced english|english (fluency|proficiency|is required)|fluency in english/i;
// "2 anos de experiência", "3+ anos", "mínimo de 2 anos" — 1 ano ainda passa
const EXIGE_ANOS = /\b([2-9]|\d{2})\s*\+?\s*anos?\s+(de\s+)?(experi|atua)|m[ií]nimo\s+de\s+([2-9]|\d{2})\s+anos/i;
// Cadastro em banco de talentos não é vaga
const NAO_E_VAGA = /cadastre-se|banco de talentos|talent pool|n[aã]o encontrou (a sua|sua) vaga/i;
const CATEGORIAS_REMOTAR = ['Programação', 'Programação Mobile', 'Data Science / Analytics', 'DevOps', 'QA', 'SysAdmin'];
const TAGS_REMOTAR_FORA = /s[eê]nior|pleno|ingl[eê]s|internacional|espanhol/i;

// Português: conta palavras comuns; vaga em inglês/espanhol fica com 0-2.
const PALAVRAS_PT = /\b(voc[eê]|vaga|experi[eê]ncia|conhecimentos?|requisitos|benef[ií]cios|atividades|responsabilidades|empresa|nossa|nosso|trabalhar|desenvolvimento|desej[aá]vel|diferenciais)\b/gi;
const emPortugues = (texto) => (String(texto).match(PALAVRAS_PT) || []).length >= 4;

const agora = Date.now();
const limite = agora - JANELA_HORAS * 3600 * 1000;
const limiteGupy = agora - JANELA_HORAS_GUPY * 3600 * 1000;

const limpar = (html) =>
  String(html ?? '')
    .replace(/<\/(p|li|h\d|div)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();

// "Buscar vagas" devolve o corpo como texto (a Gupy responde HTML). Converte
// cada resposta numa lista de objetos no formato original da fonte.
const respostas = [];
for (const item of $input.all()) {
  const corpo = item.json.data;
  if (typeof corpo !== 'string' || corpo === '') continue; // erro de rede/HTTP: ignora a fonte
  if (corpo.trimStart().startsWith('<')) {
    const m = corpo.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
    const lista = m && JSON.parse(m[1]).props?.pageProps?.initialJobList?.data;
    if (Array.isArray(lista)) respostas.push({ gupy: lista });
    continue;
  }
  let data;
  try {
    data = JSON.parse(corpo);
  } catch {
    continue;
  }
  // GitHub devolve um array de issues
  if (Array.isArray(data)) respostas.push(...data);
  else respostas.push(data);
}

const vagas = [];

for (const data of respostas) {
  // Gupy: { gupy: [...] } — só estágio (o filtro vai na URL)
  if (Array.isArray(data.gupy)) {
    for (const j of data.gupy) {
      const publicada = Date.parse(j.publishedDate);
      if (!j.name || !j.jobUrl || !(publicada >= limiteGupy)) continue;
      if (j.applicationDeadline && Date.parse(j.applicationDeadline) < agora) continue;

      const remoto = j.workplaceType === 'remote';
      const modalidade = remoto ? 'remoto' : j.workplaceType === 'hybrid' ? 'híbrido' : 'presencial';
      const cidade = [j.city, j.state].filter(Boolean).join(' / ');
      vagas.push({
        publicada,
        title: j.name,
        // o parâmetro jobBoardSource muda conforme a página; a vaga é a mesma
        url: j.jobUrl.replace(/\?.*$/, ''),
        source: 'gupy',
        company: j.careerPageName ?? '',
        nivel: `${j.name} estágio`,
        // descrição da Gupy começa pelo texto institucional da empresa: a área
        // sai só do título
        area: j.name,
        remoto,
        local: remoto || j.state === ESTADO_LOCAL || CIDADES_LOCAIS.includes(j.city),
        description:
          [
            `${j.name} — ${j.careerPageName ?? ''}`,
            'Tipo: estágio',
            `Modalidade: ${modalidade}${cidade ? ` (${cidade})` : ''}`,
            j.applicationDeadline && `Inscrições até: ${j.applicationDeadline.slice(0, 10).split('-').reverse().join('/')}`,
          ].filter(Boolean).join('\n') + '\n\n' + limpar(j.description),
      });
    }
    continue;
  }

  // Remotar: { meta, data: [...] }
  if (data.meta && Array.isArray(data.data)) {
    for (const j of data.data) {
      const publicada = Date.parse(j.createdAt);
      if (!j.title || !j.id || !(publicada >= limite) || j.expired || j.active === false) continue;

      const tags = (j.jobTags ?? []).map((t) => t.tag?.name ?? '').filter(Boolean);
      const categorias = (j.jobCategories ?? []).map((c) => c.category?.name ?? '');
      if (tags.some((t) => TAGS_REMOTAR_FORA.test(t))) continue;
      if (!categorias.some((c) => CATEGORIAS_REMOTAR.includes(c))) continue;

      const remoto = j.type === 'remote';
      const salario = j.jobSalary
        ? [j.jobSalary.from, j.jobSalary.to].filter(Boolean).join(' a ')
        : '';
      const corpo = limpar([j.subtitle, j.description, j.moreInfos].filter(Boolean).join('\n\n'));

      vagas.push({
        publicada,
        title: j.title,
        url: `https://remotar.com.br/job/${j.id}`,
        source: 'remotar',
        company: j.companyDisplayName ?? j.company?.name ?? '',
        nivel: `${j.title} ${tags.join(' ')}`,
        // as categorias já foram filtradas por CATEGORIAS_REMOTAR (todas de TI)
        area: `${j.title} ${categorias.join(' ')}`,
        remoto,
        local: remoto || LOCAL_OK.test(`${j.city ?? ''} ${j.state ?? ''}`),
        description:
          [
            `${j.title} — ${j.companyDisplayName ?? j.company?.name ?? ''}`,
            `Tags: ${tags.map((t) => t.replace(/^[^\p{L}]+/u, '')).join(', ')}`,
            `Área: ${categorias.join(', ')}`,
            !remoto && j.city && `Local: ${j.city}${j.state ? ` / ${j.state}` : ''}`,
            salario && `Salário: R$ ${salario}`,
          ].filter(Boolean).join('\n') + '\n\n' + corpo,
      });
    }
    continue;
  }

  // Himalayas: { jobs: [...] } — só vagas remotas abertas ao Brasil
  if (Array.isArray(data.jobs)) {
    for (const j of data.jobs) {
      const publicada = Number(j.pubDate) * 1000;
      const url = j.applicationLink || j.guid;
      const paises = j.locationRestrictions ?? [];
      if (!j.title || !url || !(publicada >= limite)) continue;
      if (!paises.includes('Brazil')) continue;

      const nivel = (j.seniority ?? []).join(', ');
      vagas.push({
        publicada,
        title: j.title,
        url,
        source: 'himalayas',
        company: j.companyName ?? '',
        nivel: `${j.title} ${nivel}`,
        // as categorias do Himalayas não servem: "Desenvolvimento de Negócios"
        // vem com "Estágio-em-Desenvolvimento"
        area: j.title,
        remoto: true,
        local: true,
        description:
          [
            `${j.title} — ${j.companyName ?? ''}`,
            `Nível: ${nivel || 'não informado'}`,
            `Modalidade: remoto (${paises.join(', ')})`,
          ].join('\n') + '\n\n' + limpar(j.description || j.excerpt),
      });
    }
    continue;
  }

  // GitHub (frontendbr/vagas, backend-br/vagas...): uma issue por item. A
  // modalidade vem nas labels ou no título ("[Remoto]", "Presencial - SP").
  if (data.html_url && data.title && !data.pull_request) {
    const publicada = Date.parse(data.created_at);
    if (!(publicada >= limite)) continue;

    const labels = (data.labels ?? []).map((l) => l.name).join(', ');
    const marcas = `${data.title} ${labels}`;
    const remoto = REMOTO.test(marcas);
    vagas.push({
      publicada,
      title: data.title,
      url: data.html_url,
      source: 'github',
      // a issue não tem campo de empresa; o VagaSync confere de novo com a
      // empresa que a IA extrair
      company: '',
      nivel: marcas,
      // os repositórios buscados são só de vagas de desenvolvimento
      area: `${data.title} desenvolvimento`,
      remoto,
      // sem modalidade informada, deixa passar: a IA lê o texto
      local: remoto || !PRESENCIAL.test(marcas) || LOCAL_OK.test(marcas),
      description: [data.title, labels && `Tags: ${labels}`].filter(Boolean).join('\n') + '\n\n' + limpar(data.body),
    });
  }
}

// Regras comuns a todas as fontes. O título manda no nível: "Júnior" no
// título com "pleno" só no texto (ex: "você vai trabalhar com devs plenos")
// continua valendo.
const passa = (v) =>
  v.local &&
  NIVEL_OK.test(v.nivel) &&
  !NAO_E_VAGA.test(v.title) &&
  !NIVEL_FORA.test(v.title) &&
  !AREA_FORA.test(v.title) &&
  !(NAO_TI.test(v.title) && !AREA_TI.test(v.title)) &&
  AREA_TI.test(v.area) &&
  emPortugues(v.description) &&
  !EXIGE_INGLES.test(v.description) &&
  !EXIGE_ANOS.test(v.description);

// Estágio primeiro, depois as mais novas; intercala as fontes para nenhuma
// ocupar a rodada toda.
const porFonte = {};
const vistas = new Set();
const ordem = (v) => (ESTAGIO.test(v.nivel) ? 1 : 0);
for (const v of vagas.sort((a, b) => ordem(b) - ordem(a) || b.publicada - a.publicada)) {
  if (vistas.has(v.url)) continue;
  vistas.add(v.url);
  // mesmo guard do fluxo antigo: nunca mandar item vazio para o webhook
  if (!v.title || !v.url || v.description.length < 20) continue;
  if (!passa(v)) continue;
  (porFonte[v.source] ??= []).push(v);
}

const filas = Object.values(porFonte);
const results = [];
while (results.length < MAX_CANDIDATAS && filas.some((f) => f.length)) {
  for (const fila of filas) {
    const v = fila.shift();
    if (!v || results.length >= MAX_CANDIDATAS) continue;
    results.push({
      json: {
        description: v.description.slice(0, MAX_DESCRICAO),
        url: v.url,
        source: v.source,
        title: v.title,
        company: v.company,
      },
    });
  }
}

return results;

// Fica só com as candidatas que "Checar já cadastradas" disse que são novas e
// aplica o teto da rodada sobre elas: vagas antigas que reaparecem no feed não
// ocupam lugar, então a fila nunca trava em duplicadas.
//
// Se a checagem falhar (rede, deploy antigo sem a rota), segue como antes:
// as primeiras MAX_POR_EXECUCAO candidatas, e o webhook deduplica uma a uma.
const MAX_POR_EXECUCAO = 40;

const candidatas = $('Montar vagas').all();
const resposta = $input.first()?.json ?? {};
const indices = Array.isArray(resposta.novas) ? resposta.novas : candidatas.map((_, i) => i);

return [...new Set(indices)]
  .filter((i) => Number.isInteger(i) && candidatas[i])
  .slice(0, MAX_POR_EXECUCAO)
  .map((i) => ({ json: candidatas[i].json }));
